package com.bank.depth.oltp;

import com.bank.depth.model.AccountRow;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// OLTP row-store: whole rows together; fast point get/update.
public class RowStoreOltp {
    private static final Logger log = Logger.getLogger(RowStoreOltp.class.getName());
    private final Map<String, AccountRow> rows = new HashMap<>();

    public void insert(AccountRow r) { rows.put(r.getId(), r); }

    public AccountRow getById(String id) {        // fast point read — one whole row
        log.fine(() -> "OLTP point read " + id);
        return rows.get(id);
    }

    public void updateBalance(String id, BigDecimal delta) { // fast point write
        AccountRow r = rows.get(id);
        r.setBalance(r.getBalance().add(delta));
        log.info(() -> "OLTP point write: " + id + " balance=" + r.getBalance());
    }

    public Collection<AccountRow> all() { return rows.values(); }
}
