package com.bank.depth.olap;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// OLAP column-store star schema: columns stored separately + branch dimension.
public class ColumnStoreOlap {
    private static final Logger log = Logger.getLogger(ColumnStoreOlap.class.getName());

    // fact columns (stored separately — read only what you need)
    private final List<String> branchIdCol = new ArrayList<>();
    private final List<BigDecimal> amountCol = new ArrayList<>();
    // dimension
    private final Map<String, String> dimBranch = new HashMap<>();

    public void addBranchDim(String id, String name) { dimBranch.put(id, name); }

    public void addFact(String branchId, BigDecimal amount) {
        branchIdCol.add(branchId);
        amountCol.add(amount);
    }

    // Heavy scan-and-aggregate over the fact, joined to the branch dimension.
    public Map<String, BigDecimal> totalByBranch() {
        log.info("OLAP scan-and-aggregate over " + amountCol.size() + " fact rows (columnar)");
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (int i = 0; i < amountCol.size(); i++) {
            String name = dimBranch.getOrDefault(branchIdCol.get(i), "UNKNOWN");
            totals.merge(name, amountCol.get(i), BigDecimal::add);
        }
        return totals;
    }
}
