package com.bank.depth.sync;

import com.bank.depth.oltp.RowStoreOltp;
import com.bank.depth.olap.ColumnStoreOlap;
import com.bank.depth.model.AccountRow;
import java.util.logging.Logger;

// Copies OLTP data into the OLAP star schema (CDC/ETL) — isolates workloads.
public class Syncer {
    private static final Logger log = Logger.getLogger(Syncer.class.getName());

    public void sync(RowStoreOltp oltp, ColumnStoreOlap olap) {
        log.info("SYNC OLTP → OLAP (facts + dimension)");
        for (AccountRow r : oltp.all()) {
            olap.addFact(r.getBranchId(), r.getBalance()); // simplified: balance as a measure
        }
    }
}
