package com.bank.depth;

import com.bank.depth.model.AccountRow;
import com.bank.depth.olap.ColumnStoreOlap;
import com.bank.depth.oltp.RowStoreOltp;
import com.bank.depth.sync.Syncer;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class OltpOlapDepthDemo {
    private static final Logger log = Logger.getLogger(OltpOlapDepthDemo.class.getName());

    public static void main(String[] args) {
        RowStoreOltp oltp = new RowStoreOltp();
        oltp.insert(new AccountRow("SAV2001", "BR-MUM", new BigDecimal("1000000.00")));
        oltp.insert(new AccountRow("CUR3001", "BR-MUM", new BigDecimal("250000.00")));
        oltp.insert(new AccountRow("SAV7777", "BR-DEL", new BigDecimal("500000.00")));

        log.info("=== OLTP: fast point operations ===");
        oltp.updateBalance("SAV2001", new BigDecimal("-50000.00"));
        log.info("Rajesh (point read) balance = " + oltp.getById("SAV2001").getBalance());

        log.info("=== SYNC → OLAP star schema ===");
        ColumnStoreOlap olap = new ColumnStoreOlap();
        olap.addBranchDim("BR-MUM", "Mumbai Main");
        olap.addBranchDim("BR-DEL", "Delhi Central");
        new Syncer().sync(oltp, olap);

        log.info("=== OLAP: heavy scan-and-aggregate by branch ===");
        olap.totalByBranch().forEach((branch, total) ->
            log.info("BRANCH " + branch + " total = " + total));
    }
}
